  "translations" = '{"fr":{"name":"Portfolio Personnel","description":"Site portfolio personnel responsive présentant mes projets, compétences et parcours. Vitrine de mes réalisations en développement web, IA et data, hébergée sur bahoumartoure.com avec architecture optimisée pour les performances et le SEO.","role":"Développeur Full-Stack","highlights":["Architecture moderne Next.js avec rendu hybride SSR/SSG.","Design responsive et accessible avec Tailwind CSS.","Section projets dynamique alimentée par un fichier de données structuré."],"challenges":["Optimisation SEO et performance Lighthouse.","Conception d''une structure de données projets évolutive et maintenable."]},"es":{"name":"Portafolio personal","description":"Portafolio personal responsive que presenta mis proyectos, habilidades y trayectoria. Escaparate de mis trabajos en desarrollo web, IA y datos, alojado en bahoumartoure.com con una arquitectura optimizada para el rendimiento y el SEO.","role":"Desarrollador Full-Stack","highlights":["Arquitectura moderna con Next.js y renderizado híbrido SSR/SSG.","Diseño responsive y accesible con Tailwind CSS.","Sección de proyectos dinámica alimentada por una fuente de datos estructurada."],"challenges":["Optimización del SEO y del rendimiento en Lighthouse.","Diseño de una estructura de datos de proyectos escalable y mantenible."]},"ar":{"name":"معرض الأعمال الشخصي","description":"موقع شخصي متجاوب يعرض مشاريعي ومهاراتي ومساري. واجهة لأعمالي في تطوير الويب والذكاء الاصطناعي والبيانات، مستضاف على bahoumartoure.com بمعمارية مُحسَّنة للأداء ولمحركات البحث.","role":"مطوّر Full-Stack","highlights":["معمارية حديثة بـ Next.js مع عرض هجين SSR/SSG.","تصميم متجاوب وسهل الوصول باستخدام Tailwind CSS.","قسم مشاريع ديناميكي يعتمد على مصدر بيانات منظم."],"challenges":["تحسين محركات البحث والأداء في Lighthouse.","تصميم بنية بيانات للمشاريع قابلة للتطور وسهلة الصيانة."]}}'::jsonb,
  "updatedAt" = CURRENT_TIMESTAMP
WHERE "translations" IS NULL
  AND btrim("name") = 'Portfolio Personnel'
  AND "description" = 'Site portfolio personnel responsive présentant mes projets, compétences et parcours. Vitrine de mes réalisations en développement web, IA et data, hébergée sur bahoumartoure.com avec architecture optimisée pour les performances et le SEO.'
  AND "role" = 'Full-Stack Developer'
  AND "highlights" = ARRAY['Architecture moderne Next.js avec rendu hybride SSR/SSG.', 'Design responsive et accessible avec Tailwind CSS.', 'Section projets dynamique alimentée par un fichier de données structuré.']::text[]
  AND "challenges" = ARRAY['Optimisation SEO et performance Lighthouse.', 'Conception d''une structure de données projets évolutive et maintenable.']::text[];

UPDATE "Experience" SET
  "title" = 'Looking for a summer internship (PFA)',
  "company" = 'Open to opportunities',
  "duration" = 'July 2026 – September 2026',
  "details" = ARRAY['Looking for a 2- to 3-month summer internship to apply my academic knowledge to real software projects.', 'Eager to support a technical team on Full-Stack (Spring Boot) or Data/AI development work.', 'Motivated to learn industry best practices, work with Agile methods and grow my technical skills.', 'Available on site (Oujda-Berkane, Morocco) or remotely.']::text[],
  "translations" = '{"fr":{"title":"À la recherche d''un stage d''été (PFA)","company":"À l''écoute d''opportunités","duration":"Juillet 2026 – Septembre 2026","details":["À la recherche d''un stage d''été de 2 à 3 mois pour appliquer mes connaissances académiques sur des projets Software concrets.","Désireux d''accompagner une équipe technique sur des missions en développement Full-Stack (Spring Boot) ou Data/IA.","Motivé pour apprendre les bonnes pratiques de l''industrie, travailler en méthode Agile et monter en compétences techniques.","Disponible pour des missions en présentiel (Oujda-Berkane/Maroc) ou en @Remote."]},"es":{"title":"En busca de prácticas de verano (PFA)","company":"Abierto a oportunidades","duration":"Julio de 2026 – Septiembre de 2026","details":["Busco prácticas de verano de 2 a 3 meses para aplicar mis conocimientos académicos en proyectos de software reales.","Con ganas de apoyar a un equipo técnico en tareas de desarrollo Full-Stack (Spring Boot) o de Data/IA.","Motivado para aprender las buenas prácticas del sector, trabajar con metodologías ágiles y reforzar mis competencias técnicas.","Disponible de forma presencial (Oujda-Berkane, Marruecos) o en remoto."]},"ar":{"title":"أبحث عن تدريب صيفي (PFA)","company":"منفتح على الفرص","duration":"يوليو 2026 – سبتمبر 2026","details":["أبحث عن تدريب صيفي لمدة شهرين إلى ثلاثة أشهر لتطبيق معارفي الأكاديمية على مشاريع برمجية حقيقية.","متحمس لمرافقة فريق تقني في مهام تطوير Full-Stack (Spring Boot) أو البيانات والذكاء الاصطناعي.","متحفز لتعلم أفضل ممارسات المهنة والعمل وفق منهجية Agile وتطوير مهاراتي التقنية.","متاح للعمل حضوريًا (وجدة - بركان، المغرب) أو عن بُعد."]}}'::jsonb
