UPDATE "Profile" SET "translations" = '{"fr":{"aboutTitle":"À propos de","aboutHighlight":"l''ingénieur logiciel","description":"Développeur Web & Mobile junior, DevOps, designer et blogueur. J''associe code, IA et création de contenu pour bâtir des identités de marque fortes et des expériences numériques performantes."},"es":{"aboutTitle":"Sobre","aboutHighlight":"el ingeniero de software","description":"Desarrollador web y móvil junior, DevOps, diseñador y bloguero. Combino código, IA y creación de contenido para construir identidades de marca sólidas y experiencias digitales de alto rendimiento."},"ar":{"aboutTitle":"نبذة عن","aboutHighlight":"مهندس البرمجيات","description":"مطوّر ويب وتطبيقات هاتف مبتدئ، مهتم بـ DevOps، مصمّم ومدوّن. أجمع بين البرمجة والذكاء الاصطناعي وصناعة المحتوى لبناء هويات قوية للعلامات وتجارب رقمية عالية الأداء."}}'::jsonb, "updatedAt" = CURRENT_TIMESTAMP
